('admin-navarra:6-1963751ddc','admin-navarra',6,'Los tratados internacionales válidamente celebrados forman parte del ordenamiento interno:','["Desde su firma", "Desde su ratificación por el Rey", "Cuando los aprueba el Consejo de Ministros", "Una vez publicados oficialmente en España"]'::jsonb,3,'Art. 96.1 CE','Forman parte del ordenamiento interno una vez publicados oficialmente en España.',null),
